#pragma once
#include <QString>

class QApplication;

// UI language. Korean text comes from a dictionary compiled into the executable
// (src/ui/Translations_ko.inc, generated by tools/gen_translations.py), so no .qm files are needed.
enum class Language { English, Korean };

Language savedLanguage();          // from QSettings; defaults to the system locale
void saveLanguage(Language lang);
void installLanguage(Language lang);  // replaces the application translator
Language currentLanguage();           // the installed one
QString languageName(Language lang);  // in its own language
